type ReactGAModule = typeof import("react-ga4")["default"];

const GA_MEASUREMENT_ID = process.env.REACT_APP_GA_MEASUREMENT_ID;
const SESSION_STORAGE_KEY = "analytics_session_id";
const MAX_PENDING_EVENTS = 50;
const START_EVENTS = ["pointerdown", "keydown", "scroll"] as const;

type AnalyticsEvent =
  | { type: "page_view"; page: string }
  | { type: "cta_click"; ctaName: string; location: string }
  | { type: "form_abandonment"; formName: string; step?: number }
  | { type: "form_submit"; formName: string; status: string };

let ReactGA: ReactGAModule | null = null;
let isAnalyticsEnabled = false;
let isInitialized = false;
let initializationPromise: Promise<boolean> | null = null;
let areStartListenersRegistered = false;
let lastTrackedPage = "";
let lastQueuedPage = "";
const pendingEvents: AnalyticsEvent[] = [];

const debugAnalytics = (message: string) => {
  if (process.env.NODE_ENV === "development") {
    console.info(`[analytics] ${message}`);
  }
};

const createSessionId = () => {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }

  return "10000000-1000-4000-8000-100000000000".replace(/[018]/g, (char) =>
    (
      Number(char) ^
      (Math.floor(Math.random() * 16) >> (Number(char) / 4))
    ).toString(16),
  );
};

const getAnalyticsSessionId = () => {
  if (typeof window === "undefined") return undefined;

  const savedSessionId = window.sessionStorage.getItem(SESSION_STORAGE_KEY);

  if (savedSessionId) {
    return savedSessionId;
  }

  const sessionId = createSessionId();
  window.sessionStorage.setItem(SESSION_STORAGE_KEY, sessionId);

  return sessionId;
};

const sendAnalyticsEvent = (event: AnalyticsEvent) => {
  if (!ReactGA || !isInitialized || !isAnalyticsEnabled) return;

  if (event.type === "page_view") {
    lastTrackedPage = event.page;
    lastQueuedPage = "";
    debugAnalytics(`page_view: ${event.page}`);
    ReactGA.send({
      hitType: "pageview",
      page: event.page,
      app_session_id: getAnalyticsSessionId(),
    });
    return;
  }

  if (event.type === "cta_click") {
    debugAnalytics(`cta_click: ${event.ctaName}`);
    ReactGA.event("cta_click", {
      cta_name: event.ctaName,
      location: event.location,
      app_session_id: getAnalyticsSessionId(),
    });
    return;
  }

  if (event.type === "form_abandonment") {
    debugAnalytics(`form_abandonment: ${event.formName}`);
    ReactGA.event("form_abandonment", {
      form_name: event.formName,
      step: event.step,
      app_session_id: getAnalyticsSessionId(),
    });
    return;
  }

  debugAnalytics(`form_submit: ${event.formName} (${event.status})`);
  ReactGA.event("form_submit", {
    form_name: event.formName,
    status: event.status,
    app_session_id: getAnalyticsSessionId(),
  });
};

const flushPendingEvents = () => {
  if (!isInitialized || !ReactGA || !isAnalyticsEnabled) return;

  const eventsToSend = pendingEvents.splice(0, pendingEvents.length);
  eventsToSend.forEach(sendAnalyticsEvent);
};

const enqueueAnalyticsEvent = (event: AnalyticsEvent) => {
  if (!isAnalyticsEnabled) return;

  if (isInitialized && ReactGA) {
    sendAnalyticsEvent(event);
    return;
  }

  if (pendingEvents.length >= MAX_PENDING_EVENTS) {
    pendingEvents.shift();
  }

  pendingEvents.push(event);
};

export const initAnalytics = async () => {
  if (isInitialized) return true;

  if (!GA_MEASUREMENT_ID) {
    debugAnalytics("GA4 disabled: missing REACT_APP_GA_MEASUREMENT_ID");
    return false;
  }

  if (!isAnalyticsEnabled) {
    debugAnalytics("GA4 disabled: analytics consent is not active");
    return false;
  }

  if (!initializationPromise) {
    initializationPromise = import("react-ga4")
      .then(({ default: analytics }) => {
        if (!isAnalyticsEnabled) return false;

        ReactGA = analytics;
        ReactGA.initialize(GA_MEASUREMENT_ID, {
          gaOptions: {
            anonymize_ip: true,
            allowAdFeatures: false,
            allowAdPersonalizationSignals: false,
          },
          gtagOptions: {
            send_page_view: false,
          },
        });

        isInitialized = true;
        debugAnalytics("GA4 initialized after consent and user interaction");
        flushPendingEvents();
        return true;
      })
      .catch(() => {
        initializationPromise = null;
        debugAnalytics("GA4 initialization failed");
        return false;
      });
  }

  return initializationPromise;
};

export const isAnalyticsInitialized = () => isInitialized;

export const hasAnalyticsMeasurementId = () => Boolean(GA_MEASUREMENT_ID);

const removeStartListeners = () => {
  if (typeof window === "undefined" || !areStartListenersRegistered) return;

  START_EVENTS.forEach((eventName) => {
    window.removeEventListener(eventName, handleFirstInteraction, true);
  });
  areStartListenersRegistered = false;
};

function handleFirstInteraction(event: Event) {
  if (!event.isTrusted) return;

  removeStartListeners();
  void initAnalytics();
}

export const enableAnalyticsAfterInteraction = () => {
  if (!GA_MEASUREMENT_ID || typeof window === "undefined") return;

  isAnalyticsEnabled = true;

  if (isInitialized || areStartListenersRegistered) {
    flushPendingEvents();
    return;
  }

  START_EVENTS.forEach((eventName) => {
    window.addEventListener(eventName, handleFirstInteraction, {
      capture: true,
      passive: true,
    });
  });
  areStartListenersRegistered = true;
  debugAnalytics("GA4 waiting for the first user interaction");
};

export const disableAnalytics = () => {
  isAnalyticsEnabled = false;
  pendingEvents.length = 0;
  lastQueuedPage = "";
  removeStartListeners();
};

export const trackPageView = (page: string) => {
  if (page === lastTrackedPage || page === lastQueuedPage) return;

  lastQueuedPage = page;
  enqueueAnalyticsEvent({ type: "page_view", page });
};

/*
  RODO - zasada minimalizacji:
  GA4 zbiera tylko techniczne dane pomiarowe potrzebne do statystyk uzycia:
  sciezke strony, referrer, przyblizony czas wizyty, typ urzadzenia/przegladarki
  oraz pseudonimowy identyfikator klienta/sesji. Adres IP jest anonimizowany,
  a dodatkowy app_session_id jest losowym UUID w sessionStorage, bez powiazania
  z imieniem, nazwiskiem, e-mailem ani trescia formularzy.
  Zdarzenia niestandardowe ponizej wysylaja wylacznie metadane akcji
  (nazwa CTA, nazwa formularza, krok/status), bez imienia, nazwiska, e-maila,
  hasla, tresci zadania ani kategorii. Te dane sa niezbedne do oceny, czy
  uzytkownicy znajduja kluczowe akcje, gdzie porzucaja formularz i czy submit
  konczy sie powodzeniem.
  Ograniczenie celu: dane sluza tylko do statystyk UX, bez profilowania
  reklamowego; sygnaly reklamowe GA sa wylaczone w konfiguracji.
  Cookie consent: analityka jest wlaczana dopiero po akceptacji, a biblioteka
  GA4 laduje sie dopiero po pierwszej interakcji uzytkownika.
  Retencja: w panelu GA4 nalezy ustawic przechowywanie danych na maks. 14 mies.
  Polityka prywatnosci: README dokumentuje page_view, cta_click,
  form_abandonment i form_submit wraz z celem oraz zakresem danych.

  Checklist anonimizacji:
  - IP anonimizowane na poziomie konfiguracji: anonymize_ip: true.
  - Session ID to UUID z sessionStorage, bez powiazania z danymi osobowymi.
  - Brak zbierania tresci wpisanych w formularze.
  - Retencja danych ograniczana w panelu GA4 do maks. 14 miesiecy.
  - Cookie consent blokuje inicjalizacje GA4 do czasu akceptacji.

  Weryfikacja non render-blocking:
  react-ga4 tworzy tag gtag.js dynamicznie z script.async = true i dodaje go do
  document.body, wiec skrypt nie blokuje pierwszego renderowania HTML.
*/
export const trackCtaClick = (ctaName: string, location: string) => {
  enqueueAnalyticsEvent({ type: "cta_click", ctaName, location });
};

export const trackFormAbandonment = (formName: string, step?: number) => {
  enqueueAnalyticsEvent({ type: "form_abandonment", formName, step });
};

export const trackFormSubmit = (formName: string, status: string) => {
  enqueueAnalyticsEvent({ type: "form_submit", formName, status });
};
